
from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
DATA = ROOT / "data"
OUTPUT = ROOT / "reports"
OUTPUT.mkdir(exist_ok=True)

# Load candidate scores generated by ai_matcher.py.
candidates = pd.read_csv(OUTPUT / "ai_candidate_scores.csv")
bank = pd.read_csv(DATA / "bank_lines.csv")
ledger = pd.read_csv(DATA / "ledger_entries.csv")

# Configurable threshold; tune using held-out validation data.
THRESHOLD = 0.80

# Sort highest-confidence candidates first.
candidates = candidates.sort_values(
    "match_probability",
    ascending=False,
).copy()

used_ledger = set()
used_bank = set()
accepted = []
review = []

for row in candidates.itertuples(index=False):
    ledger_id = int(row.ledger_id)
    bank_id = int(row.bank_id)
    probability = float(row.match_probability)

    if probability < THRESHOLD:
        continue

    # Do not assign a record more than once.
    if ledger_id in used_ledger or bank_id in used_bank:
        review.append({
            "ledger_id": ledger_id,
            "bank_id": bank_id,
            "match_probability": probability,
            "status": "conflict_review",
        })
        continue

    accepted.append({
        "ledger_id": ledger_id,
        "bank_id": bank_id,
        "match_probability": probability,
        "status": "matched",
    })

    used_ledger.add(ledger_id)
    used_bank.add(bank_id)

matches = pd.DataFrame(accepted)
conflicts = pd.DataFrame(review)

# Add transaction details to the accepted matches.
if not matches.empty:
    matches = matches.merge(
        ledger[["id", "reference", "counterparty", "amount", "entry_date"]],
        left_on="ledger_id",
        right_on="id",
        how="left",
    ).drop(columns=["id"])

    matches = matches.merge(
        bank[["id", "narrative", "amount", "posted_date"]],
        left_on="bank_id",
        right_on="id",
        how="left",
        suffixes=("_ledger", "_bank"),
    ).drop(columns=["id"])

matches.to_csv(OUTPUT / "ai_reconciliation_matches.csv", index=False)
conflicts.to_csv(OUTPUT / "ai_reconciliation_review.csv", index=False)

print("=== AI RECONCILIATION SUMMARY ===")
print(f"Accepted one-to-one matches: {len(matches)}")
print(f"Ledger entries matched:      {matches['ledger_id'].nunique() if not matches.empty else 0}")
print(f"Bank lines matched:          {matches['bank_id'].nunique() if not matches.empty else 0}")
print(f"Conflicting candidates:      {len(conflicts)}")
print(f"Unmatched ledger entries:    {len(ledger) - (matches['ledger_id'].nunique() if not matches.empty else 0)}")
print(f"Unmatched bank lines:        {len(bank) - (matches['bank_id'].nunique() if not matches.empty else 0)}")

print("\nSaved:")
print(OUTPUT / "ai_reconciliation_matches.csv")
print(OUTPUT / "ai_reconciliation_review.csv")

print(
    "\nNote: These matches use scores from the model trained on all candidates. "
    "They are demonstration outputs, not independent test results."
)
